using namespace std;

int sayi[2][6];
int sayilar[6];

int main() {
    int n;
    scanf("%d", &n);

    for (int i = 0, x; i < n; ++i) {
        scanf("%d", &x);
        ++sayi[0][x];
        ++sayilar[x];
    }

    for (int i = 0, x; i < n; ++i) {
        scanf("%d", &x);
        ++sayi[1][x];
        ++sayilar[x];
    }

    int sonuc = 0;
    for (int i = 1; i <= 5; ++i) {
        if (sayilar[i] % 2 != 0) {
            printf("-1");
            return 0;
        }
        sonuc += abs(sayi[0][i] - sayi[1][i]) / 2;
    }

    printf("%d", sonuc / 2);
    return 0;
}

